_choice_ansible_playbook_become_method() {
    command -v ansible-doc >/dev/null || return 0
    ansible-doc -t become -l 2>/dev/null |
        gawk 'NF >= 2 { name = $1; $1 = ""; sub(/^ +/, ""); sub(/ +$/, ""); print name "\t" $0 }'
}

_choice_ansible_playbook_connection() {
    command -v ansible-doc >/dev/null || return 0
    ansible-doc -t connection -l 2>/dev/null |
        gawk 'NF >= 2 { name = $1; $1 = ""; sub(/^ +/, ""); sub(/ +$/, ""); print name "\t" $0 }'
}

_choice_ansible_playbook_host() {
    command -v ansible-inventory >/dev/null || return 0
    local inv=() item
    for item in "${argc_inventory[@]:-}" "${argc_inventory_file[@]:-}"; do
        [[ -n "$item" ]] && inv+=(-i "$item")
    done
    ansible-inventory "${inv[@]}" --list 2>/dev/null |
        jq -b -r '(.. | objects | (.children? // empty)[]), (.. | objects | (.hosts? // empty)[])' 2>/dev/null
}

_choice_ansible_playbook_tags() {
    local pb="${argc_playbook[0]:-}" inv=() item
    [[ -n "$pb" ]] || return 0
    for item in "${argc_inventory[@]:-}" "${argc_inventory_file[@]:-}"; do
        [[ -n "$item" ]] && inv+=(-i "$item")
    done
    ansible-playbook "${inv[@]}" --list-tags "$pb" 2>/dev/null |
        gawk 'match($0, /TAGS: \[([^]]*)\]/, m) {
            n = split(m[1], a, /,[[:space:]]*/)
            for (i = 1; i <= n; i++) if (a[i] != "") print a[i]
        }'
}

_choice_ansible_playbook_task() {
    local pb="${argc_playbook[0]:-}" inv=() item
    [[ -n "$pb" ]] || return 0
    for item in "${argc_inventory[@]:-}" "${argc_inventory_file[@]:-}"; do
        [[ -n "$item" ]] && inv+=(-i "$item")
    done
    ansible-playbook "${inv[@]}" --list-tasks "$pb" 2>/dev/null |
        gawk -F '\t' 'NF >= 2 && $1 ~ /^      [^ ]/ { sub(/^ +/, "", $1); print $1 }'
}
